from solution import fib
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def fib_ref(n: int) -> int:
    """Obviously-correct reference model: F0=0, F1=1, Fn=Fn-1+Fn-2."""
    assert n >= 0
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


# ---- explicit spec examples ----
def test_spec_example_fib_10_is_55():
    assert fib(10) == 55


def test_spec_example_fib_1_is_1():
    assert fib(1) == 1


def test_spec_example_fib_8_is_21():
    assert fib(8) == 21


# ---- boundary / base cases derived from "n-th Fibonacci number" ----
def test_fib_zero_is_zero():
    # F0 = 0 by definition of Fibonacci sequence; must be int, not None.
    assert fib(0) == 0


def test_fib_zero_is_int_not_none():
    result = fib(0)
    assert result is not None
    assert isinstance(result, int)


def test_fib_base_cases():
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(2) == 1
    assert fib(3) == 2
    assert fib(4) == 3
    assert fib(5) == 5
    assert fib(6) == 8
    assert fib(7) == 13


def test_fib_returns_int_for_valid_n():
    for n in range(0, 15):
        r = fib(n)
        assert isinstance(r, int), f"fib({n}) should be int, got {type(r)}"


# ---- properties ----

@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert fib(n) == fib_ref(n)


@given(st.integers(min_value=2, max_value=30))
def test_recurrence_relation(n):
    # Fn == Fn-1 + Fn-2 for n >= 2
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=1, max_value=30))
def test_monotonic_non_decreasing(n):
    # F1 <= F2 <= F3 ... (1,1,2,3,5,...)
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=3, max_value=30))
def test_strictly_increasing_from_n3(n):
    assert fib(n + 1) > fib(n)


@given(st.integers(min_value=0, max_value=25))
def test_sum_identity(n):
    # sum_{i=0..n} Fi == F_{n+2} - 1
    total = sum(fib(i) for i in range(n + 1))
    assert total == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=30))
def test_gcd_property_consecutive_coprime(n):
    # consecutive Fibonacci numbers are coprime (for n>=1); F0=0 case: gcd(0,1)=1
    import math
    assert math.gcd(fib(n), fib(n + 1)) == 1


def test_first_20_values_match_reference():
    expected = [fib_ref(n) for n in range(20)]
    actual = [fib(n) for n in range(20)]
    assert actual == expected
